files.content:
* {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
}

body {
  display: grid;
  justify-content: center;
  align-items: center;
  min-width: 500px;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #feafe8;
}

form {
  width: 400px;
  border: 2px solid #000;
  padding: 50px;
}

label {
  display: block;
}

label span {
  display: block;
  font-weight: 800;
  font-size: 12px;
  text-transform: uppercase;
}

input[type='range'] {
  width: 100%;
  background-color: transparent;
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
}

input[type='range']::-webkit-slider-thumb {
  width: 26px;
  height: 16px;
  margin-top: -3px;
  border: 1px solid #000;
  border-radius: 0;
  background-color: #fff;
  cursor: pointer;
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
}

input[type='range']::-moz-range-thumb {
  box-sizing: border-box;
  width: 26px;
  height: 16px;
  border: 1px solid #000;
  border-radius: 0;
  background-color: #fff;
  cursor: pointer;
}

input[type='range']::-webkit-slider-runnable-track {
  width: 100%;
  height: 10px;
  border: none;
  border-radius: 0;
  background-color: #000;
  cursor: pointer;
}

input[type='range']::-moz-range-track {
  width: 100%;
  height: 10px;
  border: none;
  border-radius: 0;
  background-color: #000;
  cursor: pointer;
}

input[type="range"]:focus {
  outline: 2px solid #000;
  outline-offset: 2px;
}
